"""Tests for the Graph data structure and graph algorithms."""

from __future__ import annotations

import sys

import pytest

from depcycle.graph.graph import Graph
from depcycle.graph.node import Node
from depcycle.utils import get_stdlib_names as _get_stdlib_names


def test_stdlib_names_fallback(monkeypatch: pytest.MonkeyPatch) -> None:
    """Test standard library discovery fallback branch when sys.stdlib_module_names is missing."""
    monkeypatch.setattr(sys, "stdlib_module_names", None, raising=False)
    names = _get_stdlib_names()
    assert "os" in names
    assert "sys" in names
    assert "pathlib" in names


def test_stdlib_names_native(monkeypatch: pytest.MonkeyPatch) -> None:
    """Test standard library discovery using native sys.stdlib_module_names."""
    monkeypatch.setattr(sys, "stdlib_module_names", {"custom_std"}, raising=False)
    names = _get_stdlib_names()
    assert names == {"custom_std"}


def test_graph_basics() -> None:
    """Test basic graph node additions, retrievals, and container protocols."""
    g = Graph()
    assert len(g) == 0
    assert repr(g) == "Graph(nodes=0)"

    n1 = Node(name="alpha")
    g.add_node(n1)

    assert g.get_node("alpha") == n1
    assert g.get_node("beta") is None
    assert len(g) == 1
    assert repr(g) == "Graph(nodes=1)"

    assert list(iter(g)) == [n1]



def test_graph_metrics_and_dependents() -> None:
    """Test fan-out, fan-in, and dependent node calculations."""
    g = Graph()
    n1 = Node(name="a")
    n2 = Node(name="b")
    n3 = Node(name="c")

    for node in (n1, n2, n3):
        g.add_node(node)

    n1.add_dependency(n2)  # a -> b
    n1.add_dependency(n3)  # a -> c
    n2.add_dependency(n3)  # b -> c

    assert g.fan_out("a") == 2
    assert g.fan_out("b") == 1
    assert g.fan_out("nonexistent") == 0

    assert g.fan_in("c") == 2
    assert g.fan_in("b") == 1
    assert g.fan_in("a") == 0

    dependents_c = g.dependents("c")
    assert set(dependents_c) == {n1, n2}


def test_shortest_path() -> None:
    """Test shortest path finding via BFS under various scenarios."""
    g = Graph()
    n1 = Node(name="a")
    n2 = Node(name="b")
    n3 = Node(name="c")
    n4 = Node(name="d")

    for node in (n1, n2, n3, n4):
        g.add_node(node)

    n1.add_dependency(n2)
    n2.add_dependency(n3)

    # Missing nodes
    assert g.shortest_path("a", "missing") is None
    assert g.shortest_path("missing", "c") is None

    # Source equals target
    assert g.shortest_path("a", "a") == [n1]

    # Valid path
    path = g.shortest_path("a", "c")
    assert path == [n1, n2, n3]

    # No path (disconnected component)
    assert g.shortest_path("a", "d") is None


def test_shortest_path_visited_branch() -> None:
    g = Graph()
    n1 = Node(name="a")
    n2 = Node(name="b")
    n3 = Node(name="c")
    for n in (n1, n2, n3):
        g.add_node(n)

    # a -> b, a -> c, b -> c (c visited via b or direct)
    n1.add_dependency(n2)
    n1.add_dependency(n3)
    n2.add_dependency(n3)

    assert g.shortest_path("a", "c") == [n1, n3]


def test_find_cycles() -> None:
    """Test circular dependency detection via DFS."""
    g = Graph()
    n1 = Node(name="a")
    n2 = Node(name="b")
    n3 = Node(name="c")
    n4 = Node(name="d")

    for node in (n1, n2, n3, n4):
        g.add_node(node)

    # No cycles initially
    n1.add_dependency(n2)
    n2.add_dependency(n3)
    assert g.find_cycles() == []

    # Direct self-loop cycle on d
    n4.add_dependency(n4)
    cycles_d = g.find_cycles()
    assert len(cycles_d) == 1
    assert cycles_d[0] == [n4, n4]

    # Multi-node cycle: closing the loop c -> a
    n3.add_dependency(n1)
    cycles = g.find_cycles()
    assert len(cycles) >= 1
    flattened_names = {node.name for cycle in cycles for node in cycle}
    assert {"a", "b", "c"}.issubset(flattened_names)
